//! Rust ⇄ JavaScript parity.
//!
//! The project ships two kernels on purpose: `game/sim/*.js` is what the browser runs (no toolchain,
//! instant load), and this crate is the reference implementation that CI compiles for native and for
//! `wasm32-unknown-unknown`.
//!
//! Two kernels are only allowed to exist if they agree. The JavaScript suite *writes its answers
//! down* (`test/vectors.json`, regenerated by `node test/vectors.mjs`) and this test replays that file
//! and asserts every value to a stated tolerance. Edit a coefficient on either side and the build
//! fails here -- which is the whole point of using CI as the compiler.
//!
//! If the vectors file is absent, the test does not skip silently: it falls back to comparing against
//! libm, and says so in the log.

use odderon_kernel::{dmath, thermo};
use std::path::PathBuf;

fn vectors_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("kernel/ has a parent")
        .join("test")
        .join("vectors.json")
}

/// The vectors file is a flat object of arrays of numbers, so a whole JSON library would be a
/// dependency the kernel does not need. This reads exactly that shape and nothing else.
fn read_vectors(src: &str) -> Vec<(String, Vec<f64>)> {
    let bytes = src.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] != b'"' {
            i += 1;
            continue;
        }
        let start = i + 1;
        let mut j = start;
        while j < bytes.len() && bytes[j] != b'"' {
            j += 1;
        }
        if j >= bytes.len() {
            break;
        }
        let key = src[start..j].to_string();
        let mut k = j;
        while k < bytes.len() && bytes[k] != b'[' {
            k += 1;
        }
        if k >= bytes.len() {
            break;
        }
        let mut vals = Vec::new();
        let mut n = k + 1;
        let mut num_start: Option<usize> = None;
        while n < bytes.len() {
            let b = bytes[n];
            let numeric = b == b'-' || b == b'.' || b == b'e' || b == b'E' || b.is_ascii_digit();
            if numeric {
                if num_start.is_none() {
                    num_start = Some(n);
                }
            } else if b == b',' || b == b']' {
                if let Some(s) = num_start {
                    if let Ok(v) = src[s..n].trim().parse::<f64>() {
                        vals.push(v);
                    }
                    num_start = None;
                }
                if b == b']' {
                    break;
                }
            }
            n += 1;
        }
        out.push((key, vals));
        i = n + 1;
    }
    out
}

fn find<'a>(v: &'a [(String, Vec<f64>)], key: &str) -> Option<&'a Vec<f64>> {
    v.iter().find(|(k, _)| k == key).map(|(_, vals)| vals)
}

/// The room replay shared by both kernels. Eight lines of arithmetic, written out in
/// `test/vectors.mjs` and in `thermo::Room::step`; the point of the test is that they are the *same*
/// eight lines.
/// One second of the room, with the curtain drawn at the halfway mark. `ghi` is the last input in
/// the state vector: 1006 W/m², the measured midday clear-sky value from `test/physics.test.mjs`.
fn step_one_second(index: usize, ghi: f64, room: &mut thermo::Room) -> f64 {
    let tau = if index < 3600 { 1.0 } else { 0.05 };
    room.step(1.0, ghi, tau);
    room.node.t
}

#[test]
fn the_js_kernel_and_the_rust_kernel_agree() {
    let path = vectors_path();
    let src = match std::fs::read_to_string(&path) {
        Ok(s) => s,
        Err(e) => {
            println!("vectors not found at {path:?} ({e}); falling back to libm");
            against_libm();
            return;
        }
    };
    let v = read_vectors(&src);
    assert!(!v.is_empty(), "the vectors file parsed to nothing: {path:?}");

    // ---- transcendentals ----------------------------------------------------------------
    let sin_x = find(&v, "sin_x").expect("sin_x");
    let sin_y = find(&v, "sin_y").expect("sin_y");
    assert_eq!(sin_x.len(), sin_y.len(), "sin_x and sin_y must pair up");
    let mut worst: f64 = 0.0;
    for (x, y) in sin_x.iter().zip(sin_y.iter()) {
        worst = worst.max((dmath::sin(*x) - y).abs());
        // cos is the same reduction one quadrant over, so it is held to the same number
        let c = dmath::cos(*x);
        assert!(c.is_finite() && c.abs() <= 1.0 + 1e-12, "cos({x}) out of range");
    }
    assert!(worst < 1e-14, "sin disagrees with the JS kernel by {worst:e}");

    let exp_x = find(&v, "exp_x").expect("exp_x");
    let exp_y = find(&v, "exp_y").expect("exp_y");
    for (x, y) in exp_x.iter().zip(exp_y.iter()) {
        let rel = (dmath::exp(*x) - y).abs() / y.abs().max(1e-300);
        assert!(rel < 1e-13, "exp({x}) disagrees by {rel:e}");
    }

    let ln_x = find(&v, "ln_x").expect("ln_x");
    let ln_y = find(&v, "ln_y").expect("ln_y");
    for (x, y) in ln_x.iter().zip(ln_y.iter()) {
        assert!((dmath::ln(*x) - y).abs() < 1e-13, "ln({x}) disagrees");
    }

    if let (Some(ax), Some(ay)) = (find(&v, "atan_x"), find(&v, "atan_y")) {
        let mut worst_a: f64 = 0.0;
        for (x, y) in ax.iter().zip(ay.iter()) {
            worst_a = worst_a.max((dmath::atan(*x) - y).abs());
        }
        assert!(worst_a < 1e-14, "atan disagrees by {worst_a:e}");
    }

    // ---- the thermal solver, two hours of it -------------------------------------------------
    let st = find(&v, "room_state").expect("room_state");
    assert_eq!(st.len(), 10, "room_state carries ten numbers");
    let (js, ts) = (
        find(&v, "room_T").expect("room_T"),
        find(&v, "room_t").expect("room_t"),
    );
    assert_eq!(js.len(), ts.len(), "one temperature per sample");

    let mut room = thermo::Room {
        node: thermo::Node {
            c: st[1],
            ua_out: st[2],
            t: st[0],
        },
        t_out: st[3],
        aperture: st[4],
        ac_w: st[5],
        cop: st[6],
        setpoint: st[7],
        hysteresis: st[8],
        ac_on: false,
        duty: 0.0,
    };
    let mut worst_t: f64 = 0.0;
    for i in 0..7200 {
        let t = step_one_second(i, st[9], &mut room);
        if i % 600 == 0 {
            worst_t = worst_t.max((t - js[i / 600]).abs());
        }
    }
    worst_t = worst_t.max((room.node.t - js[js.len() - 1]).abs());
    // 1e-9 K after two hours: the two kernels are doing the same arithmetic, not merely similar
    // arithmetic. The JS side integrates in exactly the same order for exactly this reason.
    assert!(worst_t < 1e-9, "the two rooms disagree by {worst_t:e} K");
    println!(
        "parity: worst sin {worst:e}, worst room {worst_t:e} K over {} samples",
        js.len()
    );
}

fn against_libm() {
    let mut worst: f64 = 0.0;
    for i in -2000..2000 {
        let x = f64::from(i) * 0.01;
        worst = worst.max((dmath::sin(x) - x.sin()).abs());
        worst = worst.max((dmath::cos(x) - x.cos()).abs());
    }
    assert!(worst < 1e-13, "sin/cos vs libm: {worst:e}");
    for i in 1..500 {
        let x = f64::from(i) * 0.02;
        assert!((dmath::ln(x) - x.ln()).abs() < 1e-12, "ln({x})");
        let e = dmath::exp(x * 0.1);
        assert!((e - (x * 0.1).exp()).abs() / e < 1e-13, "exp({})", x * 0.1);
        assert!((dmath::atan(x) - x.atan()).abs() < 1e-14, "atan({x})");
    }
}
